generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url = env("DATABASE_URL")
}

model AuditLog {
  id String @id @default(cuid())
  actorId String?
  action String
  resource String
  metadata Json?
  createdAt DateTime @default(now())
}
